99:const DropdownMenuTrigger = React.forwardRef<DropdownMenuTriggerElement, DropdownMenuTriggerProps>(
100:  (props: ScopedProps<DropdownMenuTriggerProps>, forwardedRef) => {
101:    const { __scopeDropdownMenu, disabled = false, ...triggerProps } = props;
102:    const context = useDropdownMenuContext(TRIGGER_NAME, __scopeDropdownMenu);
103:    const menuScope = useMenuScope(__scopeDropdownMenu);
104:    return (
105:      <MenuPrimitive.Anchor asChild {...menuScope}>
106:        <Primitive.button
107:          type="button"
108:          id={context.triggerId}
109:          aria-haspopup="menu"
110:          aria-expanded={context.open}
111:          aria-controls={context.open ? context.contentId : undefined}
112:          data-state={context.open ? 'open' : 'closed'}
113:          data-disabled={disabled ? '' : undefined}
114:          disabled={disabled}
115:          {...triggerProps}
116:          ref={composeRefs(forwardedRef, context.triggerRef)}
117:          onPointerDown={composeEventHandlers(props.onPointerDown, (event) => {
118:            // only call handler if it's the left button (mousedown gets triggered by all mouse buttons)
119:            // but not when the control key is pressed (avoiding MacOS right click)
120:            if (!disabled && event.button === 0 && event.ctrlKey === false) {
121:              context.onOpenToggle();
122:              // prevent trigger focusing when opening
123:              // this allows the content to be given focus without competition
124:              if (!context.open) event.preventDefault();
125:            }
126:          })}
127:          onKeyDown={composeEventHandlers(props.onKeyDown, (event) => {
128:            if (disabled) return;
129:            if (['Enter', ' '].includes(event.key)) context.onOpenToggle();
130:            if (event.key === 'ArrowDown') context.onOpenChange(true);
131:            // prevent keydown from scrolling window / first focused item to execute
132:            // that keydown (inadvertently closing the menu)
133:            if (['Enter', ' ', 'ArrowDown'].includes(event.key)) event.preventDefault();
134:          })}
135:        />
136:      </MenuPrimitive.Anchor>
137:    );
138:  },
139:);
